import sys
from collections import deque
sys.setrecursionlimit(20000)

class N:
    def __init__(self, v):
        self.v = v
        self.l = None
        self.r = None

def build(tok):
    root = N(int(tok[0]))
    dq = deque([root])
    i = 1
    while dq and i < len(tok):
        x = dq.popleft()
        if i < len(tok):
            t = tok[i]
            i += 1
            if t != 'null':
                x.l = N(int(t))
                dq.append(x.l)
        if i < len(tok):
            t = tok[i]
            i += 1
            if t != 'null':
                x.r = N(int(t))
                dq.append(x.r)
    return root

data = sys.stdin.read().split()
K = int(data[0])
root = build(data[1:])

def collect(x):
    if x is None:
        return []
    return [x.v] + collect(x.l) + collect(x.r)

def walk(x):
    if x is None:
        return 0
    c = walk(x.l) + walk(x.r)
    if all(sum(int(ch) for ch in str(v)) == K for v in collect(x)):
        c += 1
    return c

